1. Books to Scrape

books &lt;- lapply(1:5, function(i) {

  books_pg &lt;- read_html(paste0("https://books.toscrape.com/catalogue/page-", i, ".html"))

  tibble(title = books_pg |&gt;
        html_elements("article.product_pod h3 a") |&gt;
        html_attr("title"),

        price = books_pg |&gt;
        html_elements("article.product_pod p.price_color") |&gt;
        html_text2(),

        rating = books_pg |&gt;
        html_elements("article.product_pod p.star-rating") |&gt;
        html_attr("class") |&gt;
        str_remove("star-rating ")) |&gt;

    mutate(price_gbp = parse_number(price))})

books &lt;- bind_rows(books)

head(books)

